const e=JSON.parse('[{"id":"111_111010_001","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司於 X1 年 1 月 1 日設立，對存貨採定期盤存制。1 月 25 日倉庫發生火災，燒毀大部分的存貨，盤點後僅餘存貨$5,000。火災前帳列銷貨收入$500,000，進貨$450,000。若估計毛利率 30%，則以毛利率法估計之存貨火災損失為何？","tableData":null,"images":[],"options":[{"key":"A","text":"$85,000","imageUrl":null},{"key":"B","text":"$90,000","imageUrl":null},{"key":"C","text":"$95,000","imageUrl":null},{"key":"D","text":"$100,000","imageUrl":null}],"correctAnswer":"C","explanation":"銷貨成本為$350,000，估計期末存貨應為$100,000，扣除殘值$5,000後損失為$95,000。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_002","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司期初資產總額$2,800,000、期初負債總額$1,100,000、本期銷貨收入$2,330,000、銷貨退回$30,000、期初存貨$83,000、進貨$1,620,000、進貨運費$10,000、進貨退回及折讓$30,000、期末存貨$70,000、營業費用$450,000、利息費用$50,000，稅率為 20%，則期末權益為何？","tableData":null,"images":[],"options":[{"key":"A","text":"$1,849,600","imageUrl":null},{"key":"B","text":"$1,873,600","imageUrl":null},{"key":"C","text":"$1,865,600","imageUrl":null},{"key":"D","text":"$1,887,000","imageUrl":null}],"correctAnswer":"A","explanation":"期初權益170萬，加計本期稅後淨利149,600元，得出期末權益為1,849,600元。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_003","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司於 X1 年 8 月 1 日付現$21,000 支付一年保險費，交易當時借記預付保險費，X1 年度甲公司保險費為$20,450，若甲公司 X1 年初預付保險費餘額為$11,900，請問 X1 年底預付保險費餘額為何？","tableData":null,"images":[],"options":[{"key":"A","text":"$11,350","imageUrl":null},{"key":"B","text":"$12,450","imageUrl":null},{"key":"C","text":"$29,550","imageUrl":null},{"key":"D","text":"$32,900","imageUrl":null}],"correctAnswer":"B","explanation":"期初預付11,900加付現21,000減本期保險費20,450，等於期末餘額12,450元。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_004","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"下列何者須於綜合損益表中單行列示？","tableData":null,"images":[],"options":[{"key":"A","text":"停業單位損益","imageUrl":null},{"key":"B","text":"非常損益","imageUrl":null},{"key":"C","text":"會計原則變動累積影響數","imageUrl":null},{"key":"D","text":"股利發放數","imageUrl":null}],"correctAnswer":"A","explanation":"根據國際財務報導準則，停業單位損益應於綜合損益表中單獨列示，以供投資者評估持續性經營能力。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_005","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司於民國 109 年底資產總額為 27,607 億元，權益總額為 18,506 億元，請問甲公司 109 年底的負債總額為多少？且這些資訊可由那個財務報表取得？","tableData":null,"images":[],"options":[{"key":"A","text":"46,113 億元；資產負債表","imageUrl":null},{"key":"B","text":"9,101 億元；資產負債表","imageUrl":null},{"key":"C","text":"23,057 億元；綜合損益表","imageUrl":null},{"key":"D","text":"4,551 億元；現金流量表","imageUrl":null}],"correctAnswer":"B","explanation":"負債總額等於資產減權益（27,607 - 18,506 = 9,101），此三要素均列示於資產負債表。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_006","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"沖銷應收帳款將：","tableData":null,"images":[],"options":[{"key":"A","text":"增加備抵損失","imageUrl":null},{"key":"B","text":"對備抵損失沒有影響","imageUrl":null},{"key":"C","text":"對淨利沒有影響","imageUrl":null},{"key":"D","text":"減少淨利","imageUrl":null}],"correctAnswer":"C","explanation":"沖銷分錄借記備抵損失、貸記應收帳款，僅為資產項目的互補抵銷，不影響損益表的各項淨利指標。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_007","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"在編製銀行往來調節表後，公司需作借記「應收帳款」、貸記「銀行存款」的調整分錄，請問可能是下列何者所造成的？","tableData":null,"images":[],"options":[{"key":"A","text":"在途存款","imageUrl":null},{"key":"B","text":"未兌現支票","imageUrl":null},{"key":"C","text":"存款不足退票","imageUrl":null},{"key":"D","text":"公司支付的帳款中開立$520 支票，但公司帳上誤記為$250","imageUrl":null}],"correctAnswer":"C","explanation":"存款不足退票需將原入帳之存款沖回，並重新認列對客戶之應收帳款，故作此分錄。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_008","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"本年度原報導之損益為本期淨損$18,000，後發現期末存貨高估$5,000，則正確的本期淨利（損）為：（不考慮所得稅）","tableData":null,"images":[],"options":[{"key":"A","text":"淨損$13,000","imageUrl":null},{"key":"B","text":"淨損$18,000","imageUrl":null},{"key":"C","text":"淨利$5,000","imageUrl":null},{"key":"D","text":"淨損$23,000","imageUrl":null}],"correctAnswer":"D","explanation":"期末存貨高估會低估銷貨成本並高估淨利，更正時應調減淨損18,000再減5,000，為淨損23,000。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_009","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"如果存貨之期初金額大於期末金額，且假設並無進貨退回及折讓、進貨折扣與進貨運費，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"銷貨成本大於進貨","imageUrl":null},{"key":"B","text":"銷貨成本小於進貨","imageUrl":null},{"key":"C","text":"銷貨成本等於進貨","imageUrl":null},{"key":"D","text":"銷貨成本與期末存貨的關係無法確定","imageUrl":null}],"correctAnswer":"A","explanation":"依銷貨成本公式，若期初存貨大於期末存貨，表示消耗量大於進貨量，故銷貨成本大於進貨總額。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_010","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司 X1 年期初與期末存貨分別為$5,000 與$3,000，當年度進貨$50,000、進貨退回$3,000、進貨運費$2,000，銷貨收入$80,000，銷貨退回$5,000，銷貨運費$1,000。試問 X1 年的銷貨成本為何？","tableData":null,"images":[],"options":[{"key":"A","text":"$47,000","imageUrl":null},{"key":"B","text":"$49,000","imageUrl":null},{"key":"C","text":"$51,000","imageUrl":null},{"key":"D","text":"$52,000","imageUrl":null}],"correctAnswer":"C","explanation":"計算：5,000 + (50,000 - 3,000 + 2,000) - 3,000 = 51,000元。銷貨運費屬於營業費用。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_011","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司 X6 年初發現 X4 年之期末存貨高估$25,000 與折舊費用低估$40,000，以及 X5 年之期末存貨低估$12,000。這三項錯誤對 X6 年初保留盈餘之淨影響為：（不考慮所得稅影響）","tableData":null,"images":[],"options":[{"key":"A","text":"減少$3,000","imageUrl":null},{"key":"B","text":"減少$28,000","imageUrl":null},{"key":"C","text":"減少$52,000","imageUrl":null},{"key":"D","text":"減少$53,000","imageUrl":null}],"correctAnswer":"C","explanation":"存貨高估兩年後自動抵銷，保留盈餘剩餘影響為折舊低估4萬與X5存貨低估1.2萬之合計減少數。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_012","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"取得下列何種金融資產之手續費得認列為當期費用？","tableData":null,"images":[],"options":[{"key":"A","text":"按攤銷後成本衡量之債券投資","imageUrl":null},{"key":"B","text":"透過損益按公允價值衡量之股票投資","imageUrl":null},{"key":"C","text":"透過其他綜合損益按公允價值衡量之股票投資","imageUrl":null},{"key":"D","text":"透過其他綜合損益按公允價值衡量之債券投資","imageUrl":null}],"correctAnswer":"B","explanation":"透過損益按公允價值衡量之金融資產，其取得之交易成本應於發生時即認列為當期費用。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_013","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"下列何者不屬於公司之金融資產？","tableData":null,"images":[],"options":[{"key":"A","text":"該公司之應收帳款","imageUrl":null},{"key":"B","text":"該公司之股票投資","imageUrl":null},{"key":"C","text":"該公司所持有以其他公司股票為標的之買權","imageUrl":null},{"key":"D","text":"該公司給予員工之認股權","imageUrl":null}],"correctAnswer":"D","explanation":"給予員工之認股權屬於公司的權益或勞務成本項目，而非公司持有可獲得未來現金流量之金融資產。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_014","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司 X1 年初購買一棟辦公大樓，以出租及賺取租金為目的，購買成本為$8,000,000，另支付房屋仲介及過戶登記費共計$150,000，辦公大樓於 X1 年 5 月 1 日出租，每月 10 日收取租金$200,000，甲公司後續衡量採用公允價值模式，X1 年底該辦公大樓公允價值為$9,000,000。有關該辦公大樓之會計處理，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"X1 年初借記投資性不動產$8,150,000","imageUrl":null},{"key":"B","text":"於每月 10 日收取租金時貸記投資性不動產公允價值調整利益$200,000","imageUrl":null},{"key":"C","text":"X1 年底貸記投資性不動產公允價值調整利益$850,000","imageUrl":null},{"key":"D","text":"X1 年底投資性不動產餘額$9,000,000","imageUrl":null}],"correctAnswer":"B","explanation":"收取租金時應認列為「租金收入」，並非調整資產之公允價值變動利益。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_015","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲建設公司目前有 10 個保證型保固合約，依甲公司過去經驗顯示，有 50%會請求保固，每建案之保固成本為$400,000，則甲公司應認列之負債準備為何？","tableData":null,"images":[],"options":[{"key":"A","text":"$4,000,000","imageUrl":null},{"key":"B","text":"$2,000,000","imageUrl":null},{"key":"C","text":"$900,000","imageUrl":null},{"key":"D","text":"屬或有負債，僅需附註揭露","imageUrl":null}],"correctAnswer":"B","explanation":"負債準備應按最佳估計值認列：10 個合約 × 50% 發生率 × 單案成本 40 萬 = 200 萬元。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_016","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司 X9 年 12 月 31 日有下列資產：為獲取資本增值所持有之土地$2,500,000，供自用之廠房$1,200,000，為其他企業建造之辦公大樓$1,650,000，供員工使用之宿舍大樓$1,380,000，目前尚未確定未來用途之土地$880,000。試問甲公司 X9 年 12 月 31 日投資性不動產金額為何？","tableData":null,"images":[],"options":[{"key":"A","text":"$7,610,000","imageUrl":null},{"key":"B","text":"$5,960,000","imageUrl":null},{"key":"C","text":"$4,760,000","imageUrl":null},{"key":"D","text":"$3,380,000","imageUrl":null}],"correctAnswer":"D","explanation":"投資性不動產包含資本增值之土地及用途未定之土地：250 萬 + 88 萬 = 338 萬元。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_017","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司於 X1 年 7 月 1 日購買一棟商業大樓，供出租使用，售價為$20,000,000，並支付稅捐及代書費$500,000。甲公司將此商業大樓歸類為投資性不動產，經評估可以使用 40 年，無殘值。甲公司採直線法提列折舊，X1 年租金收入為$600,000，X1 年 12 月 31 日該商業大樓的公允價值為$21,000,000。有關該不動產之會計處理，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"若採成本模式衡量，X1 年度應計提折舊$250,000","imageUrl":null},{"key":"B","text":"若採成本模式衡量，X1 年度稅前淨利將減少$256,250","imageUrl":null},{"key":"C","text":"若採成本模式衡量，X1 年度稅前淨利將增加$343,750","imageUrl":null},{"key":"D","text":"若採公允價值模式衡量，X1 年度應認列公允價值變動利益$1,000,000","imageUrl":null}],"correctAnswer":"C","explanation":"成本模式下增加數為租金收入減折舊：60 萬 - (2,050 萬 / 40 × 1/2) = 343,750 元。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_018","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"下列有關折舊的敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"折舊是將不動產、廠房及設備的成本分攤至使用期間","imageUrl":null},{"key":"B","text":"折舊方法之變動屬會計估計變動","imageUrl":null},{"key":"C","text":"在提列折舊時，成本、殘值與耐用年限，均屬於會計估計","imageUrl":null},{"key":"D","text":"對於不動產、廠房及設備項目的重大組成部分需分別提列折舊","imageUrl":null}],"correctAnswer":"C","explanation":"成本屬於根據交易事實確定的歷史記錄，並非預測或判斷而來的會計估計。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_019","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司飼養的綿羊於 X1 年初共生產羊奶 20,000 公升，每公升羊奶公允價值為$29，每公升羊奶運費$2，每公升羊奶出售成本為$3。X1 年當年發生飼料費用$100,000，採收羊奶工資$30,000，其他支出$45,000，則甲公司收成的羊奶應以多少金額入帳？","tableData":null,"images":[],"options":[{"key":"A","text":"$305,000","imageUrl":null},{"key":"B","text":"$350,000","imageUrl":null},{"key":"C","text":"$480,000","imageUrl":null},{"key":"D","text":"$520,000","imageUrl":null}],"correctAnswer":"D","explanation":"羊奶收成時應按公允價值減出售成本衡量入帳：20,000 × (29 - 3) = 520,000 元。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_020","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"下列有關負債準備之敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"未確定時點但已確定金額之負債為負債準備","imageUrl":null},{"key":"B","text":"已確定時點但未確定金額之負債為負債準備","imageUrl":null},{"key":"C","text":"未確定時點且未確定金額之負債為負債準備","imageUrl":null},{"key":"D","text":"已確定時點且已確定金額之負債為負債準備","imageUrl":null}],"correctAnswer":"D","explanation":"已確定時點且金額確定的負債屬於一般債務（如應付帳款），並非負債準備。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_021","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"出售商品附帶保證型保固服務，應於出售商品之會計期間結束日，估計未來可能提供的維修保固，並認列產品保固費用。此種會計處理係符合那一原則？","tableData":null,"images":[],"options":[{"key":"A","text":"收入認列原則","imageUrl":null},{"key":"B","text":"費用認列原則","imageUrl":null},{"key":"C","text":"成本原則","imageUrl":null},{"key":"D","text":"效益原則","imageUrl":null}],"correctAnswer":"B","explanation":"此舉是為了將產生收入的相關維修支出在同一期間認列，符合收入費用配合之費用認列原則。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_022","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"有關流動負債的敘述，下列何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"流動負債包含預收收入","imageUrl":null},{"key":"B","text":"流動負債包含預付費用","imageUrl":null},{"key":"C","text":"流動負債包含積欠特別股股利","imageUrl":null},{"key":"D","text":"流動負債包含應付股票股利","imageUrl":null}],"correctAnswer":"A","explanation":"預收收入為企業已收現但尚未提供勞務或商品之義務，屬於一年內應履行之流動負債。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_023","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司於 X1 年以 102 於公開市場買回公司債，買回當時公司債面額為$600,000，未攤銷折價為$15,000，則買回公司債之損益是多少？（不考慮交易成本）","tableData":null,"images":[],"options":[{"key":"A","text":"損失$11,700","imageUrl":null},{"key":"B","text":"損失$12,000","imageUrl":null},{"key":"C","text":"損失$27,000","imageUrl":null},{"key":"D","text":"利得$3,000","imageUrl":null}],"correctAnswer":"C","explanation":"帳面金額為 58.5 萬，買回價格為 61.2 萬（60 萬 × 1.02），兩者差額為 2.7 萬元損失。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_024","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"公司債折價攤銷是：","tableData":null,"images":[],"options":[{"key":"A","text":"減少每次付息日支付的利息","imageUrl":null},{"key":"B","text":"減少每期利息費用","imageUrl":null},{"key":"C","text":"增加應付公司債的公允價值","imageUrl":null},{"key":"D","text":"將公司債折價金額分攤至各期間","imageUrl":null}],"correctAnswer":"D","explanation":"折價攤銷係將原始發行價格與面額間之差額，依有效利息法在債券存續期間內分攤認列為利息費用。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_025","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"下列有關現金流量表之敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"現金流量表的「現金」包括約當現金、庫存現金及活期存款","imageUrl":null},{"key":"B","text":"國際財務報導準則鼓勵企業採用間接法報導營業活動之現金流量，而非採用直接法編製","imageUrl":null},{"key":"C","text":"發放現金股利可分類為營業活動","imageUrl":null},{"key":"D","text":"購買透過其他綜合損益按公允價值衡量之金融資產應分類為投資活動","imageUrl":null}],"correctAnswer":"C","explanation":"發放現金股利屬於企業回報股東之分配，應歸類為籌資（融資）活動。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_026","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"有關應付公司債之敘述，下列何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"當有效利率大於票面利率時，則公司債為折價發行","imageUrl":null},{"key":"B","text":"當有效利率小於票面利率時，則公司債的發行價格會低於面額","imageUrl":null},{"key":"C","text":"溢價攤銷會使應付公司債帳面金額減少","imageUrl":null},{"key":"D","text":"折價攤銷會使利息費用的金額逐期增加","imageUrl":null}],"correctAnswer":"B","explanation":"當有效利率小於票面利率時，市場願意溢價認購，故發行價格會高於（而非低於）債券面額。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_027","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"公司於 4 月 1 日發行應付公司債面額$200,000，五年期，票面利率 8%，每年 9 月 30 日與 3 月 31 日付息，發行時有效利率 10%，試問第一次付息日認列之利息費用為：（答案四捨五入至元）","tableData":null,"images":[],"options":[{"key":"A","text":"$9,228","imageUrl":null},{"key":"B","text":"$1,228","imageUrl":null},{"key":"C","text":"$8,000","imageUrl":null},{"key":"D","text":"$16,000","imageUrl":null}],"correctAnswer":"B","explanation":"依有效利率法計算之半年利息費用與支付現金利息間之差額調整，得出結果為 1,228 元。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_028","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"宣告現金股利對財務報表之影響不包括：","tableData":null,"images":[],"options":[{"key":"A","text":"流動負債增加","imageUrl":null},{"key":"B","text":"權益減少","imageUrl":null},{"key":"C","text":"費用增加","imageUrl":null},{"key":"D","text":"保留盈餘減少","imageUrl":null}],"correctAnswer":"C","explanation":"宣告股利係屬保留盈餘之分配，並非經營過程中所產生之費用支出。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_029","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司原發行面額$20 之普通股 450,000 股，並有保留盈餘$900,000。假設甲公司將原股份作 2：1 之股票分割，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"普通股股本不變","imageUrl":null},{"key":"B","text":"權益不變","imageUrl":null},{"key":"C","text":"每股面額變為$10","imageUrl":null},{"key":"D","text":"保留盈餘減少$450,000","imageUrl":null}],"correctAnswer":"D","explanation":"股票分割僅增加股數並等比例調低面額，並不涉及保留盈餘之轉撥或發放，其總額不變。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_030","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"下列何者非為計算本期每股盈餘之必要資訊？","tableData":null,"images":[],"options":[{"key":"A","text":"期末權益總額","imageUrl":null},{"key":"B","text":"本期淨利","imageUrl":null},{"key":"C","text":"加權平均流通在外普通股股數","imageUrl":null},{"key":"D","text":"公司發行特別股之股利率","imageUrl":null}],"correctAnswer":"A","explanation":"計算每股盈餘所需資訊為本期淨利、特別股股利及普通股加權平均數，不需用到期末權益總額。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_031","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司 X2 年 1 月 1 日流通在外 100,000 股普通股，4 月 1 日發放 10%股票股利，7 月 1 日購買庫藏普通股 10,000 股，10 月 1 日現金增資發行 20,000 股普通股，12 月 31 日分割普通股 1 股為 2 股。試問，甲公司計算 X2 年每股盈餘時，普通股加權平均流通在外股數為何？","tableData":null,"images":[],"options":[{"key":"A","text":"110,000 股","imageUrl":null},{"key":"B","text":"120,000 股","imageUrl":null},{"key":"C","text":"220,000 股","imageUrl":null},{"key":"D","text":"240,000 股","imageUrl":null}],"correctAnswer":"C","explanation":"經追溯股票股利與分割計算：(110,000 - 5,000 + 5,000) × 2 = 220,000 股。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_032","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司成立於 X1 年初，該公司發行 3%、累積、部分參加至 6%之特別股 8,000 股及普通股 12,000 股，每股面額均為$10。若該公司 X1 年至 X3 年間並未再發行或買回該公司股份，且 X1 年至 X3 年各年度分配之現金股利分別為$1,000、$2,000、$14,000，試問普通股股東 X3 年可收到之現金股利總額為：","tableData":null,"images":[],"options":[{"key":"A","text":"$4,880","imageUrl":null},{"key":"B","text":"$6,600","imageUrl":null},{"key":"C","text":"$7,400","imageUrl":null},{"key":"D","text":"$9,120","imageUrl":null}],"correctAnswer":"C","explanation":"X3 年剩餘股利由兩類股比例分配，普通股可得基本額加剩餘參與額，計算總計為 7,400 元。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_033","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"以間接法編製營業活動現金流量，下列何者應自本期淨利中減去以計算來自營業活動之現金流量？","tableData":null,"images":[],"options":[{"key":"A","text":"應收帳款帳面金額之淨減少數","imageUrl":null},{"key":"B","text":"存貨帳面金額之淨增加數","imageUrl":null},{"key":"C","text":"低於帳面金額之機器設備出售價格","imageUrl":null},{"key":"D","text":"應付帳款帳面金額之淨增加數","imageUrl":null}],"correctAnswer":"B","explanation":"存貨增加代表支付現金購買資產但尚未認列為費用，在計算現金流量時應自淨利中扣除該增加額。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_034","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"下列有關現金流量表的敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"現金流量表列報企業投資活動的現金流入與流出","imageUrl":null},{"key":"B","text":"現金流量表中的現金包括約當現金","imageUrl":null},{"key":"C","text":"現金流量表的編製方式有直接法與間接法","imageUrl":null},{"key":"D","text":"購買機器設備之現金流出屬於營業活動","imageUrl":null}],"correctAnswer":"D","explanation":"購買機器設備屬於獲取長期資產的行為，應歸類為「投資活動」之現金流出。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_035","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"公司發行公司債時，有關發行成本的會計處理，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"公司債發行時作為當期費用處理","imageUrl":null},{"key":"B","text":"公司債到期時轉作為費用處理","imageUrl":null},{"key":"C","text":"自公司債發行面額中扣除","imageUrl":null},{"key":"D","text":"作為公司債發行取得金額的減項","imageUrl":null}],"correctAnswer":"D","explanation":"發行成本應列為公司債帳面金額之減項，並反映在實際籌資金額中。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_036","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司宣告發放現金股利，則其權益和普通股權益報酬率所受影響分別為何？","tableData":null,"images":[],"options":[{"key":"A","text":"增加；增加","imageUrl":null},{"key":"B","text":"增加；減少","imageUrl":null},{"key":"C","text":"減少；增加","imageUrl":null},{"key":"D","text":"減少；減少","imageUrl":null}],"correctAnswer":"C","explanation":"宣告股利使權益總額（分母）減少，在淨利（分子）不變下，股權報酬率會相對增加。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_037","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司 X3 年的淨利為$800,000，累積特別股股本$2,000,000，股利率 10%。若 X3 年的股東權益為$10,000,000，則 X3 年的普通股股東權益報酬率為：","tableData":null,"images":[],"options":[{"key":"A","text":"6.0%","imageUrl":null},{"key":"B","text":"7.5%","imageUrl":null},{"key":"C","text":"8.0%","imageUrl":null},{"key":"D","text":"9.5%","imageUrl":null}],"correctAnswer":"B","explanation":"(800,000 - 200,000) / (10,000,000 - 2,000,000) = 600,000 / 8,000,000 = 7.5%。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_038","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司速動比率為 1，淨利率為 25%，沖銷應收帳款將導致：","tableData":null,"images":[],"options":[{"key":"A","text":"速動比率下降，淨利率不變","imageUrl":null},{"key":"B","text":"速動比率不變，淨利率下降","imageUrl":null},{"key":"C","text":"兩項比率均不變","imageUrl":null},{"key":"D","text":"兩項比率均下降","imageUrl":null}],"correctAnswer":"C","explanation":"沖銷分錄借貸皆屬流動資產項目，其淨額不變，故速動比率不變，且無損益科目不影響淨利率。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_039","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"丙公司在 X9 年的財務資料顯示：期初存貨$100,000，期末存貨$500,000，銷貨成本$900,000，銷貨收入$1,200,000。若存貨週轉率以期初存貨與期末存貨之簡單平均數計算，且一年以 365 天計，下列敘述何者正確？（答案四捨五入至整數）","tableData":null,"images":[],"options":[{"key":"A","text":"存貨週轉率為 4","imageUrl":null},{"key":"B","text":"存貨週轉率為 3","imageUrl":null},{"key":"C","text":"存貨週轉平均天數為 95","imageUrl":null},{"key":"D","text":"存貨週轉平均天數為 135","imageUrl":null}],"correctAnswer":"B","explanation":"存貨週轉率 = 900,000 / ((100,000 + 500,000) / 2) = 3 次。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_040","category":"economics","stageId":"111_111010_508","type":"multiple-choice","difficulty":2,"text":"甲公司採定期盤存制，若 X1 年期末存貨高估且未更正，則有關該錯誤之影響，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"X1 年之銷貨成本高估","imageUrl":null},{"key":"B","text":"X1 年之保留盈餘低估","imageUrl":null},{"key":"C","text":"X2 年之銷貨成本高估","imageUrl":null},{"key":"D","text":"X2 年之保留盈餘低估","imageUrl":null}],"correctAnswer":"C","explanation":"X1期末存貨高估即為X2期初存貨高估，進而導致X2年可售商品成本與銷貨成本均偏高。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","508","會計","會計學大意","測驗題"],"certificationType":"111年公務人員初等考試"}]');export{e as default};
